validator:
function validate(input) {
  const [{ TeamStats = [] }] = input;
  const ids = new Set(), names = new Set();
  for (const row of TeamStats) {
    if (row.some((v) => v === null)) return 'TeamStats rows may not contain null.';
    const [id, name, played, wins, draws, losses] = row;
    if (ids.has(id)) return `team_id ${id} appears twice.`;
    ids.add(id);
    const key = name.toLowerCase();
    if (names.has(key)) return `team_name ${name} appears twice.`;
    names.add(key);
    if (wins < 0 || draws < 0 || losses < 0) return `Team ${id} has a negative count.`;
    if (played !== wins + draws + losses) return `Team ${id}: matches_played must equal wins + draws + losses.`;
  }
  return null;
}

