function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const small = size === 'small';
  const clubs = ['Arsenal', 'Chelsea', 'Everton', 'Fulham', 'Liverpool', 'Manchester City', 'Newcastle', 'Tottenham', 'Wolves', 'Brentford'];
  for (let i = clubs.length - 1; i > 0; i--) { const j = pick(i + 1); [clubs[i], clubs[j]] = [clubs[j], clubs[i]]; }
  const count = small ? pick(9) : 2000;
  const played = small ? [0, 3, 4, 4, 5][pick(5)] : 38;
  const rows = [];
  for (let i = 0; i < count; i++) {
    const total = small && rand() < 0.2 ? pick(6) : played;
    const wins = pick(total + 1), draws = pick(total - wins + 1);
    const name = small ? clubs[i] : `Team ${String(i + 1).padStart(4, '0')}`;
    rows.push([small ? i * 2 + 1 + pick(2) : i + 1, name, total, wins, draws, total - wins - draws]);
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ TeamStats: rows }];
}
